/*LGSETC00035.updateCodeValSetList*/
	UPDATE LGCOM_INQUIRY_TERMS_CRT_SQL_M
	   SET inquiry_terms_crt_sql_name    = #{valueSetName}
	     , apply_start_date		 		 = TO_DATE(#{applyStartDate},'YYYY-MM-DD')
	 	 , apply_end_date		  		 = TO_DATE(#{applyEndDate},'YYYY-MM-DD')
	 	 , source_column_name	  		 = #{sourceColumnName}		
	 	 , meaning_column_name	  		 = #{meaningColumnName}
	 	 , sql_text				  		 = #{sqlText}
	 	 , from_sql_text		  		 = #{fromSqlText}
	 	 , where_sql_text		  		 = #{whereSqlText}
	 	 , rule_sql_text		  		 = #{ruleSqlText}
	 	 , dynamic_sql_text		  		 = #{dynamicSqlText}
	     , last_updated_by    	  		 = #{sessionUserId}
	     , last_update_date    	  		 = SYSDATE
	 WHERE inquiry_terms_creation_sql_Id = #{valueSetId}
